function getLang() {
  return localStorage.getItem("nesticaLang") || "ar";
}

function setLang(lang) {
  localStorage.setItem("nesticaLang", lang);

  document.documentElement.lang = lang;
  document.documentElement.dir = lang === "ar" ? "rtl" : "ltr";

  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.getAttribute("data-i18n");

    if (translations[lang] && translations[lang][key]) {
      el.textContent = translations[lang][key];
    }
  });

  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const key = el.getAttribute("data-i18n-placeholder");

    if (translations[lang] && translations[lang][key]) {
      el.setAttribute("placeholder", translations[lang][key]);
    }
  });

  document.querySelectorAll("[data-ar][data-en]").forEach((el) => {
    const value = el.getAttribute(
      lang === "ar" ? "data-ar" : "data-en"
    );

    if (value) {
      el.textContent = value;
    }
  });
}

function toggleLanguage() {
  setLang(getLang() === "ar" ? "en" : "ar");
}

function getTheme() {
  return localStorage.getItem("nesticaTheme") || "light";
}

function setTheme(theme) {
  localStorage.setItem("nesticaTheme", theme);
  document.documentElement.setAttribute("data-bs-theme", theme);
}

function toggleTheme() {
  setTheme(getTheme() === "dark" ? "light" : "dark");
}

document.addEventListener("click", (e) => {
  const action = e.target
    .closest("[data-action]")
    ?.getAttribute("data-action");

  if (action === "toggle-language") toggleLanguage();
  if (action === "toggle-theme") toggleTheme();
});

document.addEventListener("DOMContentLoaded", () => {
  setTheme(getTheme());
  setLang(getLang());

  const year = document.getElementById("year");

  if (year) {
    year.textContent = new Date().getFullYear();
  }

  if (typeof updateCartCount === "function") {
    updateCartCount();
  }

  if (typeof renderCart === "function") {
    renderCart();
  }

  updateOfferControls();

  document.getElementById("offersSlider")?.addEventListener("scroll", updateOfferControls);

  const input = document.getElementById("productSearchInput");

  if (input) {
    input.addEventListener("input", filterProducts);
  }
});

function scrollOffers(direction) {
  const slider = document.getElementById("offersSlider");

  if (!slider) return;

  const step = 320;
  const maxScroll = Math.max(0, slider.scrollWidth - slider.clientWidth);
  const nextPosition = Math.min(
    maxScroll,
    Math.max(0, slider.scrollLeft + direction * step)
  );

  slider.scrollTo({
    left: nextPosition,
    behavior: "smooth"
  });

  window.setTimeout(updateOfferControls, 250);
}

function updateOfferControls() {
  const slider = document.getElementById("offersSlider");
  const prev = document.getElementById("offersPrev");
  const next = document.getElementById("offersNext");

  if (!slider || !prev || !next) return;

  const maxScroll = Math.max(0, slider.scrollWidth - slider.clientWidth);

  prev.disabled = slider.scrollLeft <= 2;
  next.disabled = slider.scrollLeft >= maxScroll - 2;
}

function filterProducts() {
  updateOfferControls();

  document.getElementById("offersSlider")?.addEventListener("scroll", updateOfferControls);

  const input = document.getElementById("productSearchInput");

  const query = (input?.value || "")
    .trim()
    .toLowerCase();

  const items = document.querySelectorAll(".product-list-item");

  let visible = 0;

  items.forEach((item) => {
    const card = item.querySelector("[data-product-card]");

    const haystack = `
      ${card?.dataset.name || ""}
      ${card?.dataset.category || ""}
      ${item.textContent || ""}
    `.toLowerCase();

    const show =
      !query || haystack.includes(query);

    item.classList.toggle("d-none", !show);

    if (show) visible += 1;
  });

  document
    .getElementById("noProductsFound")
    ?.classList.toggle("d-none", visible !== 0);
}

function changeMainImage(src) {
  const img = document.getElementById("mainProductImage");

  if (img) {
    img.src = src;
  }
}

function toggleNotes() {
  const custom = document.getElementById("requestTypeCustom")?.checked;

  const notesBox = document.getElementById("notesBox");

  if (notesBox) {
    notesBox.style.display = custom ? "block" : "none";
  }
}